#include <iostream>
#include <initializer_list>
#include <memory>
#include <stdexcept>

class IntArray {
private:
    size_t m_size;
    std::unique_ptr<int[]> m_ptr;

public:
    IntArray(std::initializer_list<int> list)
        : m_size(list.size()), m_ptr(std::make_unique<int[]>(list.size())) {
        size_t i = 0;
        for (int val : list) {
            m_ptr[i++] = val;
        }
    }

    size_t size() const noexcept { return m_size; }

    int& operator[](size_t index) {
        if (index >= m_size) {
            throw std::out_of_range("Index out of range");
        }
        return m_ptr[index];
    }

    const int& operator[](size_t index) const {
        if (index >= m_size) {
            throw std::out_of_range("Index out of range");
        }
        return m_ptr[index];
    }
};

void printFirst(const IntArray& arr) {
    std::cout << "First element (const): " << arr[0] << "\n";
}

int main() {
    IntArray arr{10, 20, 30, 40};
    printFirst(arr);
    arr[0] = 99; // calls non-const operator[]
    std::cout << "Modified arr[0]: " << arr[0] << "\n";
    return 0;
}

#include <iostream>

class HugeInt {
private:
    long long m_val;

public:
    HugeInt(long long v = 0) : m_val(v) {}

    long long getVal() const noexcept { return m_val; }

    // Member operator+: handles HugeInt + long long
    HugeInt operator+(long long rhs) const {
        return HugeInt(m_val + rhs);
    }

    // Member operator+: handles HugeInt + HugeInt
    HugeInt operator+(const HugeInt& rhs) const {
        return HugeInt(m_val + rhs.m_val);
    }
};

// Non-member operator+: handles long long + HugeInt for commutativity
HugeInt operator+(long long lhs, const HugeInt& rhs) {
    return rhs + lhs; // Reuses member function
}

int main() {
    HugeInt num(500);
    HugeInt res1 = num + 25; // calls HugeInt::operator+(long long)
    HugeInt res2 = 25 + num; // calls non-member operator+(long long, HugeInt)

    std::cout << "res1: " << res1.getVal() << "\n";
    std::cout << "res2: " << res2.getVal() << "\n";
    return 0;
}

#include <iostream>

class BoundedBuffer {
private:
    int m_capacity;

public:
    // Marked explicit to prevent accidental int -> BoundedBuffer conversions
    explicit BoundedBuffer(int cap) : m_capacity(cap) {}

    int getCapacity() const noexcept { return m_capacity; }

    // explicit conversion operator to int (C++11)
    explicit operator int() const noexcept {
        return m_capacity;
    }
};

void displayBuffer(const BoundedBuffer& buf) {
    std::cout << "Buffer capacity: " << buf.getCapacity() << "\n";
}

int main() {
    BoundedBuffer buf(64);
    displayBuffer(buf);

    // displayBuffer(128); // Error: cannot convert 'int' to 'const BoundedBuffer&'
    displayBuffer(BoundedBuffer(128)); // OK: Explicit creation

    // Explicit cast operator in action
    int cap = static_cast<int>(buf);
    std::cout << "Extracted capacity as int: " << cap << "\n";

    return 0;
}
